// Bug Fix Template
// Issue: Profile picture upload functionality crashes when uploading large files
// Root Cause: Lack of file size validation before upload
// Fix: Validate file size before upload and show user-friendly error message if file is too large

import React, { useState } from 'react';
import { Upload } from 'antd';
import ImageUploader from '../ImageUploader';
import { uploadProfilePicture } from '../api';

const UserProfileModule = () => {
  const [file, setFile] = useState(null);
  const [error, setError] = useState(null);

  const handleFileChange = (info) => {
    const file = info.file;
    const fileSize = file.size / (1024 * 1024); // convert to MB

    if (fileSize > 5) {
      setError('File size exceeds the maximum limit of 5MB');
      return;
    }

    setFile(file);
  };

  const handleUpload = () => {
    if (!file) return;

    const formData = new FormData();
    formData.append('profilePicture', file);

    uploadProfilePicture(formData)
      .then((response) => {
        console.log(response);
      })
      .catch((error) => {
        console.error(error);
      });
  };

  return (
    <div>
      <Upload
        beforeUpload={handleFileChange}
        onChange={handleFileChange}
        maxCount={1}
      >
        <button>Upload Profile Picture</button>
      </Upload>
      {error && <div style={{ color: 'red' }}>{error}</div>}
      <button onClick={handleUpload}>Save Changes</button>
    </div>
  );
};

export default UserProfileModule;
